create table if not exists public.account_deletion_requests(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, status text not null default 'pending', created_at timestamptz not null default now()); alter table public.account_deletion_requests enable row level security; drop policy if exists adr_select on public.account_deletion_requests; drop policy if exists adr_insert on public.account_deletion_requests; create policy adr_select on public.account_deletion_requests for select to authenticated using (user_id = auth.uid()); create policy adr_insert on public.account_deletion_requests for insert to authenticated with check (user_id = auth.uid());
